script:
html { scroll-behavior: smooth; }
::selection { background: #2F9158; color: #FFFFFF; }

html.sp-js .sp-rise { opacity: 0; transform: translateY(20px); }
html.sp-js .sp-rise.sp-in {
  opacity: 1; transform: none;
  transition: opacity 0.85s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}
html.sp-js .sp-d1.sp-in { transition-delay: 0.12s; }
html.sp-js .sp-d2.sp-in { transition-delay: 0.24s; }

.sp-grow { flex-grow: 1; flex-shrink: 1; min-width: 0; }

.sp-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1.5px;
  transition: background-size 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
.sp-ul:hover { background-size: 100% 1.5px; }

.sp-btn { transition: transform 0.25s ease, box-shadow 0.25s ease,
  filter 0.25s ease; }
.sp-btn:hover { transform: translateY(-2px); filter: brightness(1.06);
  box-shadow: 0 12px 26px rgba(47, 145, 88, 0.3); }
.sp-btn-o { transition: border-color 0.25s ease, transform 0.25s ease; }
.sp-btn-o:hover { border-color: #2F9158; transform: translateY(-2px); }
.sp-btn-w { transition: transform 0.25s ease, box-shadow 0.25s ease; }
.sp-btn-w:hover { transform: translateY(-2px);
  box-shadow: 0 12px 26px rgba(20, 40, 30, 0.25); }

.sp-card { transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
  box-shadow 0.35s ease; }
.sp-card:hover { transform: translateY(-4px);
  box-shadow: 0 18px 40px rgba(30, 53, 42, 0.08); }

.sp-chip { transition: background-color 0.25s ease, transform 0.25s ease; }
.sp-chip:hover { background-color: #CFE9DA; transform: translateY(-2px); }

html.sp-js .sp-check .sp-tick { opacity: 0; transform: scale(0.3); }
html.sp-js .sp-check.sp-in .sp-tick { opacity: 1; transform: none;
  transition: opacity 0.3s ease, transform 0.45s
    cubic-bezier(0.34, 1.56, 0.64, 1); }

html.sp-js .sp-float { animation: sp-bob 6s ease-in-out infinite; }
@keyframes sp-bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  html.sp-js .sp-float { animation: none; }
}
